-- Ownership, JSON references and business transitions are checked by feature services.

CREATE TABLE people (
  id TEXT NOT NULL PRIMARY KEY CHECK(length(id) BETWEEN 1 AND 80 AND length(trim(id)) > 0),
  version INTEGER NOT NULL DEFAULT 1 CHECK(version >= 1),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  name TEXT NOT NULL,
  bio TEXT NOT NULL,
  avatar_path TEXT,
  CHECK(updated_at >= created_at)
) STRICT;

CREATE TABLE places (
  id TEXT NOT NULL PRIMARY KEY CHECK(length(id) BETWEEN 1 AND 80 AND length(trim(id)) > 0),
  version INTEGER NOT NULL DEFAULT 1 CHECK(version >= 1),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  name TEXT NOT NULL,
  longitude REAL NOT NULL,
  latitude REAL NOT NULL,
  address TEXT,
  provider TEXT NOT NULL,
  external_id TEXT,
  building_key TEXT,
  source_url TEXT,
  attribution TEXT NOT NULL,
  fetched_at INTEGER,
  CHECK(updated_at >= created_at),
  UNIQUE(provider, external_id),
  CHECK(longitude BETWEEN -180 AND 180),
  CHECK(latitude BETWEEN -90 AND 90)
) STRICT;

CREATE TABLE records (
  id TEXT NOT NULL PRIMARY KEY CHECK(length(id) BETWEEN 1 AND 80 AND length(trim(id)) > 0),
  version INTEGER NOT NULL DEFAULT 1 CHECK(version >= 1),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  person_id TEXT NOT NULL REFERENCES people(id) ON DELETE RESTRICT,
  kind TEXT NOT NULL CHECK(kind IN ('experience', 'diary', 'memo')),
  visit_id TEXT REFERENCES visits(id) ON DELETE SET NULL,
  place_id TEXT REFERENCES places(id) ON DELETE RESTRICT,
  occurred_at INTEGER,
  ended_at INTEGER,
  time_precision TEXT NOT NULL CHECK(time_precision IN ('exact', 'approximate', 'unknown')),
  body TEXT NOT NULL,
  purposes_json TEXT NOT NULL CHECK(json_valid(purposes_json) AND json_type(purposes_json)='array'),
  activities_json TEXT NOT NULL CHECK(json_valid(activities_json) AND json_type(activities_json)='array'),
  impression TEXT NOT NULL,
  period_answers_json TEXT NOT NULL CHECK(json_valid(period_answers_json) AND json_type(period_answers_json)='object'),
  bookmarked INTEGER NOT NULL CHECK(bookmarked IN (0, 1)),
  use_for_suggestions INTEGER NOT NULL CHECK(use_for_suggestions IN (0, 1)),
  topic_key TEXT,
  visibility TEXT NOT NULL CHECK(visibility IN ('private', 'selected', 'public')),
  shared_with_json TEXT NOT NULL CHECK(json_valid(shared_with_json) AND json_type(shared_with_json)='array'),
  CHECK(updated_at >= created_at),
  CHECK(ended_at IS NULL OR (occurred_at IS NOT NULL AND ended_at >= occurred_at)),
  CHECK(time_precision != 'unknown' OR (occurred_at IS NULL AND ended_at IS NULL)),
  CHECK(visit_id IS NULL OR (kind='experience' AND place_id IS NULL AND occurred_at IS NULL AND ended_at IS NULL AND time_precision='unknown')),
  CHECK((visibility='selected' AND json_array_length(shared_with_json)>0) OR (visibility!='selected' AND json_array_length(shared_with_json)=0))
) STRICT;

CREATE INDEX records_idx_0 ON records(person_id, occurred_at);

CREATE INDEX records_idx_1 ON records(visit_id);

CREATE INDEX records_idx_2 ON records(visibility, topic_key);

CREATE INDEX records_idx_3 ON records(place_id);

