  kind TEXT NOT NULL CHECK(kind IN ('analysis', 'comparison')),
  input_key TEXT NOT NULL,
  source_refs_json TEXT NOT NULL CHECK(json_valid(source_refs_json) AND json_type(source_refs_json)='array'),
  range_start INTEGER,
  range_end INTEGER,
  timezone TEXT NOT NULL,
