  review TEXT CHECK(review IN ('agree', 'disagree', 'unsure', 'edit')),
  review_note TEXT,
  reviewed_at INTEGER,
  CHECK(updated_at >= created_at),
  CHECK(kind!='analysis' OR (range_start IS NOT NULL AND range_end IS NOT NULL)),
  CHECK((range_start IS NULL AND range_end IS NULL) OR (range_start IS NOT NULL AND range_end IS NOT NULL AND range_end > range_start)),
  CHECK(review IS NULL OR reviewed_at IS NOT NULL)
) STRICT;

